function generateWeeksSelect(){$("#startWeekYear").on("change",function(){fillWeekSelect($(this).val(),$("#startWeekWeek"))});$("#endWeekYear").on("change",function(){fillWeekSelect($(this).val(),$("#endWeekWeek"))});fillWeekSelect($("#startWeekYear").val(),$("#startWeekWeek"));fillWeekSelect($("#endWeekYear").val(),$("#endWeekWeek"))}function generateWeeksByYear(n){n=parseInt(n);let t=firstWeekOfYear(n),r=[],i=1;for(;;){let u=new Date(t);u.setDate(t.getDate()+6);let f=`${t.getFullYear()}/${t.getMonth()+1}/${t.getDate()}(${["日","一","二","三","四","五","六"][t.getDay()]})`,e=`${u.getFullYear()}/${u.getMonth()+1}/${u.getDate()}(${["日","一","二","三","四","五","六"][u.getDay()]})`;if(r.push({value:i,text:`第${i}週 ${f}~${e}`}),u.getFullYear()>n)break;t.setDate(t.getDate()+7);i++}return r}function fillWeekSelect(n,t){let i=generateWeeksByYear(n);t.empty();i.forEach(n=>{t.append(new Option(n.text,n.value))})}